UPDATE public.site_content SET data = jsonb_set(data, '{fa}', '[["عضویت IRAN چیست؟", "اشتراکِ ماهانه‌ای که به کلِ کاتالوگ ما — آثار اوریجینال، مستندها و مجموعه‌های منتخب — دسترسی می‌دهد. آثار تازه به‌طور منظم اضافه می‌شود. با ۷ روز آزمایش رایگان شروع کنید."], ["هزینه چقدر است؟ آزمایش رایگان وجود دارد؟", "قیمت هنگام پرداخت به ارز محلی شما نشان داده می‌شود. اعضای جدید ۷ روز آزمایش رایگان دارند — در این مدت مبلغی برداشت نمی‌شود و هر زمان می‌توانید لغو کنید."], ["تفاوت عضویت و بلیت ویژه چیست؟", "بیشترِ فیلم‌ها با عضویت به‌صورت نامحدود پخش می‌شوند. آثار ویژه جداگانه به‌صورت اجاره‌ی ۴۸ ساعته فروخته می‌شوند، حتی برای اعضا. صفحه‌ی هر فیلم دقیقاً نشان می‌دهد کدام مورد است."], ["بلیتِ ویژه را چقدر می‌توانم تماشا کنم؟", "۴۸ ساعت از لحظه‌ای که پخش را شروع کنید. در این بازه می‌توانید مکث، ادامه و هر چند بار که خواستید بازتماشا کنید."], ["آیا می‌توانم هر زمان لغو کنم؟", "بله. از حساب ← مدیریت اشتراک لغو کنید. دسترسیِ شما تا پایانِ دوره‌ی پرداخت‌شده‌ی فعلی ادامه می‌یابد."], ["از چه دستگاه‌هایی پشتیبانی می‌شود؟", "هر مرورگرِ مدرن روی موبایل، تبلت، لپ‌تاپ یا تلویزیون هوشمند. AirPlay و Chromecast هر جا که مرورگر اجازه دهد کار می‌کنند."], ["از کجای جهان قابل تماشاست؟", "سراسر جهان. تعداد کمی از فیلم‌ها ممکن است محدودیتِ کشوری از سمتِ فیلم‌ساز داشته باشند؛ این محدودیت‌ها پیش از خرید نمایش داده می‌شود."], ["زیرنویس در دسترس است؟", "بله. هر فیلمِ فارسی‌زبان زیرنویسِ انگلیسیِ باکیفیت دارد. زیرنویسِ فارسی هرجا که در دسترس باشد اضافه می‌شود."], ["فیلم‌سازان چطور پرداخت می‌شوند؟", "مستقیم، با تقسیمِ درآمدِ شفاف بر هر بلیت و هر تماشای عضویت. مبالغِ «حمایت از فیلم‌ساز» مستقیم به هنرمند می‌رسد."], ["بازگشت وجه چطور کار می‌کند؟", "دوره‌ی آزمایش رایگان هیچ مبلغی ندارد. تمدیدِ عضویت تا ۱۴ روز قابل بازگشت است اگر در آن دوره کمتر از ۶۰ دقیقه تماشا کرده باشید. بلیت‌های ویژه پس از شروع پخش قابل بازگشت نیستند، مگر در صورتِ نقصِ فنی از سمتِ ما. به صفحه‌ی بازگشتِ وجه مراجعه کنید."]]'::jsonb) WHERE key='faq';
UPDATE public.site_content SET data = jsonb_set(data, '{hero,fa,subtitle}', '"فیلم‌های کوتاه ایرانی، در دسترس همه‌ی جهان. ۷ روز آزمایش رایگان — هر زمان لغو کنید."'::jsonb) WHERE key='settings';
UPDATE public.site_content SET data = jsonb_set(data, '{help,fa}', '{"title": "چطور می‌توانیم کمک کنیم؟", "kicker": "مرکز راهنما", "cards": [{"icon": "account", "heading": "حساب و ورود", "desc": "از صفحه‌ی حساب می‌توانید رمز عبور را تغییر دهید، ایمیل را به‌روزرسانی کنید یا زبان را عوض کنید."}, {"icon": "ticket", "heading": "عضویت و بلیت‌ها", "desc": "عضویت و دوره‌ی آزمایشی رایگان را در صفحه‌ی حساب مدیریت کنید. بلیت‌های ویژه، بازه‌ی تماشا و وضعیت پخش در «بلیت‌های من» نمایش داده می‌شود."}, {"icon": "billing", "heading": "پرداخت و رسیدها", "desc": "رسیدها پس از هر پرداخت به‌صورت خودکار ایمیل می‌شوند. برای پرسش‌های مالی یا بازگشت وجه به info@ir.show بنویسید."}], "body": "<h3>هنوز مشکل دارید؟</h3>\n<p>بیشترِ مشکلاتِ پخش با تازه‌سازی صفحه یا تعویض مرورگر برطرف می‌شود. اگر فیلم پخش نمی‌شود، ورود مدام قطع می‌شود یا خریدتان فعال نشد، با ایمیل حساب و نام فیلم به <a class=\"inline\" href=\"mailto:info@ir.show\">info@ir.show</a> پیام بدهید. ظرف یک روزِ کاری پاسخ می‌دهیم.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{about,fa}', '{"title": "فیلم‌های کوتاه ایرانی، در دسترس همه‌ی جهان.", "kicker": "درباره", "body": "<p>ایران خانه‌ای آنلاین برای سینمای کوتاه ایران است. فیلم‌سازان مستقل، برنامه‌ریزی منتخب، پرداخت منصفانه — و امکان تماشا از هر جای جهان.</p>\n<h3>چطور کار می‌کند</h3>\n<ul>\n<li><strong>عضویت.</strong> اشتراک ماهانه با ۷ روز آزمایش رایگان به کل کاتالوگ — آثار اوریجینال، مستندها و مجموعه‌های منتخب — دسترسی می‌دهد. هر زمان می‌توانید لغو کنید.</li>\n<li><strong>بلیت‌های ویژه.</strong> برخی آثارِ تازه به‌صورت اجاره‌ی ۴۸ ساعته جداگانه فروخته می‌شوند، حتی برای اعضا. صفحه‌ی هر فیلم نشان می‌دهد که شامل عضویت است یا ویژه.</li>\n<li><strong>حمایت مستقیم.</strong> در صفحه‌ی هر فیلم گزینه‌ی «حمایت از فیلم‌ساز» وجود دارد. این مبلغ مستقیم به هنرمند می‌رسد.</li>\n</ul>\n<h3>برای چه کسانی است</h3>\n<p>برای هر کسی که سینمای ایران برایش اهمیت دارد و برای فیلم‌سازانی که خانه‌ای پاکیزه برای آثارشان می‌خواهند. <a class=\"inline\" href=\"/submit\">فیلم خود را ارسال کنید</a> یا <a class=\"inline\" href=\"/contact\">با ما در تماس باشید</a>.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{press,fa}', '{"title": "رسانه و خبرگزاری‌ها.", "kicker": "رسانه", "body": "<p>برای مصاحبه، اسکرینر، پوششِ جشنواره‌ای یا همکاری، با توضیحی کوتاه درباره‌ی رسانه و موضوع کار خود به <a class=\"inline\" href=\"mailto:info@ir.show\">info@ir.show</a> ایمیل بزنید. ظرف دو روزِ کاری پاسخ می‌دهیم.</p>\n<h3>کیت رسانه</h3>\n<ul>\n<li>اقلامِ برند — لوگو، مونوگرام، رنگ‌ها. در صورت درخواست ارسال می‌شود.</li>\n<li>بیوگرافی کارگردان و فیلم، عکس‌ها و پوسترها — برای هر اثر به‌صورت جداگانه.</li>\n<li>نقل‌قول‌ها و امکانِ مصاحبه‌ی نوشتاری یا تصویری با بنیان‌گذاران.</li>\n</ul>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{terms,fa}', '{"title": "شرایط استفاده.", "kicker": "حقوقی", "body": "<p>با استفاده از ایران، این شرایط را می‌پذیرید. کوشیده‌ایم ساده بنویسیم. اگر چیزی روشن نیست به <a class=\"inline\" href=\"mailto:info@ir.show\">info@ir.show</a> ایمیل بزنید.</p>\n<h3>حساب کاربری</h3>\n<p>رمز عبورتان را خصوصی نگه دارید. هر شخص یک حساب. می‌توانید روی چند دستگاه وارد شوید، تا ۲ پخش هم‌زمان.</p>\n<h3>عضویت و آزمایش رایگان</h3>\n<p>اعضای جدید ۷ روز آزمایش رایگان دارند. در این مدت مبلغی برداشت نمی‌شود و هر زمان می‌توانید از حساب ← مدیریت اشتراک لغو کنید. پس از پایان آزمایش، عضویت ماهانه با همان قیمتی که هنگام پرداخت دیده‌اید تمدید می‌شود، تا زمانی که خودتان لغو کنید.</p>\n<h3>بلیت‌های ویژه</h3>\n<p>بلیت ویژه به شما اجازه می‌دهد یک فیلم را به‌صورت شخصی به مدت ۴۸ ساعت از لحظه‌ی شروع پخش (یا بازه‌ای که هنگام خرید اعلام شده) تماشا کنید. پس از شروع پخش، بلیت قابل بازگشت نیست، مگر اینکه نقصِ فنی از سمت ما مانع تماشا شده باشد. به <a class=\"inline\" href=\"/refunds\">بازگشت وجه</a> مراجعه کنید.</p>\n<h3>محتوا و حقوق</h3>\n<p>تمامی فیلم‌ها، آثار هنری و متن‌ها متعلق به سازندگانشان است یا تحت مجوز در اختیار ایران قرار گرفته. اجازه‌ی دانلود، کپی، بازنشر، پخش عمومی یا استفاده‌ی این آثار خارج از پخش‌کننده‌ی سایت را ندارید.</p>\n<h3>استفاده‌ی مجاز</h3>\n<p>اسکریپینگ، دور زدنِ کنترل‌های دسترسی و اشتراک‌گذاری تجاری حساب ممنوع است. حساب‌هایی که این شرایط را نقض کنند ممکن است معلق شوند.</p>\n<h3>تغییرات</h3>\n<p>ممکن است این شرایط را به‌روزرسانی کنیم. تغییرات مهم از طریق ایمیل یا داخل سایت اعلام می‌شود. ادامه‌ی استفاده به معنی پذیرشِ به‌روزرسانی است.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{submit,fa}', '{"title": "فیلم کوتاه خود را ارسال کنید.", "kicker": "برای فیلم‌سازان", "body": "<p>در هر فصل تعداد محدودی فیلم کوتاه ایرانی منتشر می‌کنیم. ارسال‌ها در طول سال باز است و به هر فیلم‌ساز پاسخ می‌دهیم.</p>\n<h3>چه آثاری انتخاب می‌کنیم</h3>\n<ul>\n<li>فیلم‌های کوتاه فیلم‌سازان ایرانی، داخل یا خارج از ایران.</li>\n<li>صدای متمایز. هر قالبی — داستانی، مستند، ترکیبی، انیمیشن، تجربی.</li>\n<li>چه آثارِ جشنواره‌ای، چه نخستین کارها — هر دو پذیرفته می‌شود.</li>\n</ul>\n<h3>مشخصات فنی</h3>\n<ul>\n<li>مستر: ProRes 422 HQ یا H.264، حداقل 1080p، ترجیحاً ۲۴ فریم.</li>\n<li>صدا: استریو، LUFS −۲۳، بدون کلیپینگ.</li>\n<li>زیرنویس: SRT تمیزِ فارسی و انگلیسی، یا زیرنویس انگلیسیِ سوختهٔ روی فیلم برای آثار فارسی‌زبان.</li>\n<li>کیتِ مطبوعاتی (PDF): بیو کارگردان، خلاصه، دو عکس (۳۸۴۰×۲۱۶۰)، پوستر.</li>\n</ul>\n<h3>روش ارسال</h3>\n<p>یک لینک اسکرینر خصوصی (Vimeo، Frame.io یا مشابه)، کیت مطبوعاتی و یادداشتی کوتاه درباره‌ی فیلم به <a class=\"inline\" href=\"mailto:info@ir.show\">info@ir.show</a> ایمیل کنید. ظرف دو هفته پاسخ می‌دهیم.</p>\n<h3>درآمد و حقوق</h3>\n<p>آثار منتخب مجوزِ پخشِ غیرانحصاری دریافت می‌کنند با تقسیم درآمد شفاف بر هر بلیت و عبور مستقیم مبلغِ حمایت. حقوقِ جشنواره‌ای و فایلِ مستر همچنان متعلق به شماست.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{careers,fa}', '{"title": "همکاری با ایران.", "kicker": "همکاری", "body": "<p>ما تیمی کوچک و دورکار هستیم که با وسواس ایران را می‌سازیم. آرام استخدام می‌کنیم و منصفانه پرداخت می‌کنیم.</p>\n<h3>چطور کار می‌کنیم</h3>\n<ul>\n<li>دورکارِ نخست، با هم‌پوشانی در ساعاتِ اروپا.</li>\n<li>دوزبانه — انگلیسی و فارسی.</li>\n<li>کار طولانی‌مدت بر کارِ روزمره. کیفیت بر شتاب.</li>\n</ul>\n<h3>موقعیت‌های باز</h3>\n<p>هم‌اکنون موقعیتِ عمومی باز نداریم. اگر کارتان در محصول، طراحی، مهندسی، برنامه‌ریزی یا روابط با فیلم‌سازان با ما هم‌سو است، یادداشتی کوتاه و چند لینک به <a class=\"inline\" href=\"mailto:info@ir.show\">info@ir.show</a> بفرستید.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{contact,fa}', '{"title": "با ما در تماس باشید.", "kicker": "تماس", "body": "<p>هر پیامی را می‌خوانیم و شخصاً پاسخ می‌دهیم — معمولاً ظرف دو روزِ کاری. برای مشکلاتِ فوری پخش به <a class=\"inline\" href=\"mailto:info@ir.show\">info@ir.show</a> ایمیل بزنید.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{cookies,fa}', '{"title": "کوکی‌ها.", "kicker": "حقوقی", "body": "<p>تعدادِ کمی کوکی برای اجرای سرویس و درکِ کلی نحوه‌ی استفاده به کار می‌بریم.</p>\n<h3>ضروری</h3>\n<p>نشستِ ورود، تنظیمِ زبان و وضعیتِ پخش. سایت بدون این‌ها کار نمی‌کند.</p>\n<h3>تحلیل</h3>\n<p>داده‌های ناشناسِ استفاده تا تجربه را بهتر کنیم. بدون ردیابی تبلیغاتی، بدون به‌اشتراک‌گذاری پروفایل با شرکت‌های دیگر.</p>\n<h3>انتخابِ شما</h3>\n<p>هر زمان می‌توانید کوکی‌ها را در مرورگرتان پاک کنید — با این کار از حساب خارج می‌شوید و تنظیمِ زبان نیز ریست می‌شود.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{devices,fa}', '{"title": "هر جا که برایتان راحت‌تر است تماشا کنید.", "kicker": "دستگاه‌های پشتیبانی‌شده", "body": "<p>ایران روی هر دستگاهِ مدرنی پخش می‌شود. خریدهای شما به حسابتان متصل است نه به سخت‌افزار — هرجا وارد شوید، می‌توانید ادامه دهید.</p>\n<h3>وب</h3>\n<ul>\n<li>کروم، سافاری، فایرفاکس و اج — نسخه‌ی فعلی و قبلی.</li>\n<li>وبِ دسکتاپ و موبایل، با پشتیبانی از تصویر در تصویر و تمام‌صفحه.</li>\n</ul>\n<h3>موبایل</h3>\n<ul>\n<li>سافاری iOS و کروم روی iOS 15 و بالاتر.</li>\n<li>کروم اندروید روی اندروید 10 و بالاتر.</li>\n</ul>\n<h3>تلویزیون و صفحه‌های بزرگ</h3>\n<ul>\n<li>AirPlay از آیفون، آیپد یا مک به Apple TV.</li>\n<li>Chromecast از کروم روی دسکتاپ و اندروید.</li>\n<li>اپلیکیشن‌های Apple TV و Android TV در دستِ توسعه است.</li>\n</ul>\n<p>سرعتِ ۵ مگابیت برای HD کافی است. ۱۰ مگابیت تجربه‌ای روان‌تر می‌دهد.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{privacy,fa}', '{"title": "سیاست حریم خصوصی.", "kicker": "حقوقی", "body": "<p>تنها کمترین چیزی را که برای اجرای سرویس لازم است جمع می‌کنیم. داده‌های شما را نمی‌فروشیم و تبلیغاتِ شخصِ ثالث اجرا نمی‌کنیم.</p>\n<h3>چه چیزی جمع می‌کنیم</h3>\n<ul>\n<li><strong>حساب:</strong> ایمیل، نامِ اختیاری، تنظیمِ زبان.</li>\n<li><strong>پرداخت‌ها:</strong> سوابقِ خرید و رسیدها. اطلاعاتِ کارت توسط ارائه‌دهنده‌ی پرداخت ما مدیریت می‌شود — شماره‌ی کاملِ کارتِ شما را هرگز نمی‌بینیم.</li>\n<li><strong>پخش:</strong> داده‌های فنی برای پخش و ادامه‌ی استریم.</li>\n<li><strong>پشتیبانی:</strong> هر پیامی که برای ما می‌فرستید.</li>\n</ul>\n<h3>چطور استفاده می‌کنیم</h3>\n<p>برای ارائه‌ی فیلم‌هایی که پول داده‌اید، ارسالِ ایمیل‌های تراکنشی (رسیدها، تغییرات حساب، یادآوری آزمایش)، پاسخ به پشتیبانی و بهبود سرویس.</p>\n<h3>حقوقِ شما</h3>\n<p>هر زمان می‌توانید به داده‌هایتان دسترسی پیدا کنید، آن‌ها را خروجی بگیرید، اصلاح یا حذف کنید. به <a class=\"inline\" href=\"mailto:info@ir.show\">info@ir.show</a> ایمیل بزنید؛ ظرفِ ۳۰ روز اقدام می‌کنیم.</p>\n<h3>نگه‌داری</h3>\n<p>سوابقِ حساب و خرید را در زمانِ فعال بودنِ حساب نگه می‌داریم و پس از آن تا مدتی که قوانینِ مالیاتی و حسابداری ایجاب می‌کند.</p>\n<h3>انتقالِ بین‌المللی</h3>\n<p>زیرساختِ ما در سراسر جهان کار می‌کند. ممکن است داده‌های شما تحت محافظت‌های قراردادیِ استاندارد در کشورهایی به جز کشورِ شما پردازش شود.</p>"}'::jsonb) WHERE key='pages';
UPDATE public.site_content SET data = jsonb_set(data, '{refunds,fa}', '{"title": "بازگشت وجه و لغو.", "kicker": "حقوقی", "body": "<p>می‌خواهیم همه از چیزی که پول می‌دهند راضی باشند. بازگشتِ وجه این‌طور کار می‌کند.</p>\n<h3>دوره‌ی آزمایش رایگان</h3>\n<p>۷ روز آزمایشِ شما رایگان است. در این مدت هر زمان از حساب ← مدیریت اشتراک لغو کنید، هیچ مبلغی برداشت نمی‌شود.</p>\n<h3>تمدیدِ عضویت</h3>\n<p>لغو را فراموش کرده‌اید؟ ظرفِ ۱۴ روز پس از تمدید به ما ایمیل بزنید و کلِ مبلغ را برمی‌گردانیم، به شرطی که در آن دوره کمتر از ۶۰ دقیقه از محتوای عضویت تماشا کرده باشید.</p>\n<h3>بلیت‌های ویژه</h3>\n<p>بلیت‌های ویژه پس از شروع پخش قابل بازگشت نیستند. اگر نقصِ فنی از سمتِ ما مانع تماشای کامل شده باشد، بازگشتِ کاملِ مبلغ یا اجاره‌ی رایگانِ مجدد — به انتخابِ شما — انجام می‌شود.</p>\n<h3>حمایت از فیلم‌ساز</h3>\n<p>مبالغ حمایت قابل بازگشت نیستند — این مبلغ مستقیماً به هنرمند پرداخت می‌شود.</p>\n<h3>چطور درخواستِ بازگشت بدهیم</h3>\n<p>با ایمیلِ حساب و شماره‌ی سفارش یا بلیت به <a class=\"inline\" href=\"mailto:info@ir.show\">info@ir.show</a> پیام بدهید. بیشترِ بازگشت‌ها ظرفِ ۵ روزِ کاری پردازش می‌شود.</p>"}'::jsonb) WHERE key='pages';